#nullable enable // autogenerated

using System;
using MongoDB.Bson.Serialization.Attributes;

namespace PVZEngine.Level
{
    [Serializable]
    public class ConveyorPoolPatchAddEntry : ConveyorPoolPatch
    {
        public ConveyorPoolPatchAddEntry(NamespaceID id, int value, int minCount = 1)
        {
            ID = id;
            Count = value;
            MinCount = minCount;
        }
        public override void Patch(IConveyorPatchTarget target)
        {
            target.AddEntry(ID, Count, MinCount);
        }
        public override object Clone()
        {
            return new ConveyorPoolPatchAddEntry(ID, Count, MinCount);
        }
        [BsonElement]
        public NamespaceID ID { get; set; }
        [BsonElement]
        public int Count { get; set; }
        [BsonElement]
        public int MinCount { get; set; }
    }
}